def _tri_to_espn(tri: str) -> str:
    s = str(tri or "").strip().upper()
    fix = {
        "GSW": "GS",
        "NOP": "NO",
        "NYK": "NY",
        "UTA": "UTAH",
        "WAS": "WSH",
        "SAS": "SA",
        "PHX": "PHO",
    }
    return fix.get(s, s)


def _espn_to_tri(abbr: str) -> str:
    s = str(abbr or "").strip().upper()
    fix = {
        "GS": "GSW",
        "NO": "NOP",
        "NY": "NYK",
        "UTAH": "UTA",
        "WSH": "WAS",
        "SA": "SAS",
        "PHO": "PHX",
    }
    return fix.get(s, s)


